// TailorPro service worker (generated by scripts/make-sw.mjs from this template). Do not edit out/sw.js.
// Only the app shell is cached. Authenticated API responses and storage URLs are never cached (SECURITY.md section 6):
// every cross-origin request (Supabase) and every non-GET request is left alone.
const CACHE = '__CACHE__';
const PRECACHE = __PRECACHE__;

self.addEventListener('install', (event) => {
  // No skipWaiting here: a new version waits until the user chooses to update, so open tabs are never swapped silently.
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(PRECACHE)));
});

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('shell-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

// Next.js requests route payloads as /dir/__next.a.b.__PAGE__.txt but a static export stores them as
// /dir/__next.a/b/__PAGE__.txt. Hosts normally need a rewrite; the worker does it, which also makes them work offline.
function exportedPath(pathname) {
  const m = /^(.*\/)__next\.([^/]+)\.txt$/.exec(pathname);
  if (!m) return pathname;
  const parts = m[2].split('.');
  if (parts.length === 1) return pathname;
  return m[1] + '__next.' + parts[0] + '/' + parts.slice(1).join('/') + '.txt';
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return; // never touch Supabase or any other origin
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const path = exportedPath(url.pathname);
    // pages are cached under the address they are served from (/route/), so they keep that address's security headers
    const hit = (await cache.match(path)) || (await cache.match(path, { ignoreSearch: true }));
    if (hit) return hit;
    try {
      return await fetch(req);
    } catch (err) {
      if (req.mode === 'navigate') {
        const notFound = await cache.match('/404.html');
        if (notFound) return new Response(notFound.body, { status: 404, headers: notFound.headers });
      }
      return Response.error();
    }
  })());
});
